from pathlib import Path

path = Path(__file__).parents[1] / "dist" / "admin.js"
text = path.read_text(encoding="utf-8")

text = text.replace(
    "timeWindow='all',statusFilter='all',autoRefresh=true",
    "timeWindow='today',statusFilter='all',autoRefresh=true,dateStart='',dateEnd=''",
)

def replace_between(start: str, end: str, replacement: str):
    global text
    a = text.index(start)
    b = text.index(end, a)
    text = text[:a] + replacement.rstrip() + "\n" + text[b:]

